#!/usr/bin/env python3
"""Generate src/wavelet_tables.rs from OpenAssetTools' IwiWaveletDecoder.cpp.

Usage: python scripts/gen_wavelet_tables.py <OpenAssetTools>/src/ObjImage/Image/IwiWaveletDecoder.cpp

The Huffman codeword tables are copied mechanically so no number is typed by hand.
OpenAssetTools is GPL-3.0 (https://github.com/Laupetin/OpenAssetTools); see ATTRIBUTION.md.
"""
import re, sys

src = open(sys.argv[1], encoding="utf-8").read()
out = [
    "// @generated by scripts/gen_wavelet_tables.py from OpenAssetTools' IwiWaveletDecoder.cpp (GPL-3.0).",
    "// Each entry is (LSB-first code, bit count, value); i16::MIN is the escape value.",
    "",
    "pub const ESCAPE: i16 = i16::MIN;",
    "",
]
for cpp, rs, count in (("BLUE_CODEWORDS", "BLUE", 180), ("RED_GREEN_CODEWORDS", "RED_GREEN", 80), ("ALPHA_CODEWORDS", "ALPHA", 108)):
    m = re.search(cpp + r"\s*=\s*std::to_array<HuffmanCodeword>\(\{(.*?)\}\);", src, re.S)
    body = m.group(1)
    items = re.findall(r"\{\s*(0x[0-9A-Fa-f]+)\s*,\s*(\d+)\s*,\s*(ESCAPE_VALUE|-?\d+)\s*\}", body)
    assert len(items) == count, (cpp, len(items))
    out.append(f"pub static {rs}: [(u16, u8, i16); {count}] = [")
    line = "   "
    for code, bits, val in items:
        val = "ESCAPE" if val == "ESCAPE_VALUE" else val
        cell = f" ({code}, {bits}, {val}),"
        if len(line) + len(cell) > 100:
            out.append(line)
            line = "   "
        line += cell
    out.append(line)
    out.append("];")
    out.append("")
open("src/wavelet_tables.rs", "w", encoding="utf-8", newline="\n").write("\n".join(out))
print("ok")
